{
 "title": "Hashcat Password Cracker Execution",
 "description": "Detects execution of Hashcat.exe with command line arguments referencing a SAM file and a password list, indicative of credential access via password cracking.",
 "tags": [
  "attack.credential-access",
  "attack.t1110.002"
 ],
 "logsource_category": "process_creation",
 "groups": [
  {
   "name": "selection",
   "fields": [
    {
     "field": "Image",
     "modifier": "exact",
     "values": [
      "Hashcat.exe"
     ]
    },
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "SAM"
     ]
    },
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "Password list"
     ]
    }
   ]
  }
 ],
 "condition": "selection",
 "falsepositives": [
  "Legitimate use of Hashcat for authorized password recovery may trigger this rule."
 ],
 "level": "high"
}

